#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long q;
    cin >> q;
    vector<long long> ns(q);
    for (int i = 0; i < q; i++) cin >> ns[i];

    for (long long i = 0; i < q; i++) {
        long long x = ns[i];
        int last = -1, best = 0, pos = 0;
        while (x) {
            if (x & 1) {
                if (last >= 0 && pos - last > best) best = pos - last;
                last = pos;
            }
            x >>= 1;
            pos++;
        }
        cout << (i ? " " : "") << best;
    }
    cout << "\n";

    return 0;
}

